"""GCU400 专属 ``aten::_nested_view_from_jagged_copy`` 实现。

本算子的数据面是一个平坦整块拷贝：``empty_like`` 新缓冲 + 逐元素搬运，
随后交给 :func:`_nested_view_from_jagged` 包成 jagged 视图。原实现的
``BLOCK_SIZE=1024`` + ``grid=cdiv(n, 1024)`` 在 GCU400 上付逐 program
派发税（实测约 52ns/program）：2M 元素 2048 programs 107µs、16.7M 元素
16384 programs 843µs，拷贝本体反而被完全掩盖。

本实现把拷贝换成网格跨步（grid-stride）分档派发（_stack / detach_copy
同款手法，2026-11-13 定标）：

* ``itemsize <= 4`` 且字节 8 对齐且 <=2GB 且 ``lanes >= 524288``（>=4MB，
  32768-lane 块 >=16 programs）：宽通道 —— 输入/输出
  ``view(-1).view(torch.int64)`` 按 8 字节 lane 搬运，固定 32768-lane
  块 + grid cap 256 + 块跨步循环，整除时特化免掩码；逐元素地址运算与
  访存请求降为 1/2（fp32）到 1/4（fp16/bf16）；
* 其余（<4MB、8 字节 dtype、非对齐、超大）：元素路径网格跨步，按尺寸
  两档——``n <= 16384`` 复刻旧版 ``BLOCK=1024`` 单发（官方 bench 该段
  3.04-3.27µs 稳定，BLOCK 16384 在小 n 的 16384-lane 掩码空转实测
  多付 ~1µs）；更大尺寸用固定 ``BLOCK=16384`` masked 块 + grid cap 256
  + 块跨步循环；
* 元素数越过 int32 安全域（``> 2^31 - 2^15``）时切换 int64 偏移臂，
  避免 ``cdiv`` 精确块数在 2^31 边界溢出截断。

宽通道不在小尺寸启用：探针实测 tiny 宽块（<=4096 lanes）在官方 bench
进程态下回退（fp16 n=512 BLOCK128=11.6µs vs 元素路径 ~3µs），而该
尺寸段拷贝本就 launch-bound，宽通道无收益。

launch 用三连重试包裹，吸收外部转换器冷编译偶发 SIGSEGV
（compiler_problems/P02）；零元素跳过 launch，非连续输入先
``contiguous()``（与公版语义一致）。
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.ops._nested_view_from_jagged import _nested_view_from_jagged

logger = logging.getLogger(__name__)

# 宽通道路径（int64 视图，8 字节 lane，_stack 探针 2026-11-13 定标）：
# 仅在 lanes >= _WIDE_LARGE_MIN_LANES 时启用 —— 固定 32768-lane 大块 +
# grid cap 256 + 块跨步循环；阈值取 16*32768，保证至少 16 个 program，
# 低于该值回到元素路径（大块 program 数不足反而劣化，小尺寸为
# launch-bound 段，宽通道无收益）。
_WIDE_LARGE_MIN_LANES = 524288
_WIDE_BLOCK = 32768
_WIDE_GRID_CAP = 256
_WIDE_LARGE_WARPS = 8

# 元素路径（中档 / 8 字节 dtype / 非对齐 / int64 域回退）。
# 小尺寸档 n <= _FLAT_SMALL_MAX_ELEMENTS 复刻旧版 BLOCK=1024 单发
# （官方 bench 实测该段 3.04-3.27µs 稳定；BLOCK 16384 在 n=512 时
# 16384-lane 掩码空转多付 ~1µs。detach_copy 在 1B dtype 曾测得相反
# 结论——固定大块优于贴身小块，该结论不跨 itemsize/进程态迁移）。
# 大 BLOCK 只用于中档以上。
_FLAT_BLOCK = 16384
_FLAT_GRID_CAP = 256
_FLAT_WARPS = 8
_FLAT_SMALL_BLOCK = 1024
_FLAT_SMALL_MAX_ELEMENTS = 16384
_FLAT_SMALL_WARPS = 4
# n <= 2^31 - 2^15 时 (cdiv(n, BLOCK)-1)*BLOCK + BLOCK-1 仍落在 int32 内；
# 越过该值切换 int64 偏移臂（n = 2^31-1 时 int32 cdiv 溢出截断块数，
# detach_copy 探针实测为静默错值）。
_FLAT_I32_MAX_ELEMENTS = (1 << 31) - (1 << 15)

# 宽通道的 int32 偏移安全域按总字节数守卫：bytes <= 2^31-1 时
# lanes < 2^28，任何 BLOCK_X=32768 的块偏移都远离 2^31。
_I32_SAFE_BYTES = (1 << 31) - 1

# 外部 /opt/triton_gcu 转换器冷编译偶发 SIGSEGV（compiler_problems/P02），
# 概率性、不留缓存条目、重试即可通过；确定性失败在重试耗尽后原样抛出。
_TOOLCHAIN_COMPILE_RETRIES = 3


@triton.jit
def _nvj_copy_wide_kernel(
    src_lanes_ptr,
    dst_lanes_ptr,
    num_lanes,
    chunks_per_program,
    BLOCK_X: tl.constexpr,
    MASKED: tl.constexpr,
):
    """宽通道路径：int64 视图按 8 字节 lane 整块搬运。

    输入与输出都以 ``view(torch.int64)`` 重解释，每条 lane 搬 8 字节，
    逐元素地址运算与访存请求缩减为 1/2（fp32）到 1/4（fp16/bf16）。
    host 侧已按总字节数守卫 int32 溢出，全部索引保持 int32。
    ``MASKED == False`` 时（整除且单 chunk）特化掉尾块掩码。
    """
    pid = tl.program_id(axis=0)
    num_programs = tl.num_programs(axis=0)
    for chunk_index in range(chunks_per_program):
        block_index = pid + chunk_index * num_programs
        offsets = block_index * BLOCK_X + tl.arange(0, BLOCK_X)
        if MASKED:
            active = offsets < num_lanes
            tl.store(
                dst_lanes_ptr + offsets,
                tl.load(src_lanes_ptr + offsets, mask=active),
                mask=active,
            )
        else:
            tl.store(dst_lanes_ptr + offsets, tl.load(src_lanes_ptr + offsets))


@triton.jit
def _nvj_copy_flat_kernel(
    src_ptr,
    dst_ptr,
    n_elements,
    chunks_per_program,
    BLOCK_X: tl.constexpr,
    IDX64: tl.constexpr,
):
    """元素路径：网格跨步逐元素搬运，小/中尺寸与非宽通道 dtype 的主路径。

    ``IDX64 == True`` 时偏移链显式 widening 到 int64，覆盖元素数越过
    int32 安全域的巨缓冲（正确性臂，性能不在 benchmark 口径内）。
    """
    pid = tl.program_id(axis=0)
    num_programs = tl.num_programs(axis=0)
    for chunk_index in range(chunks_per_program):
        block_index = pid + chunk_index * num_programs
        if IDX64:
            offsets = block_index.to(tl.int64) * BLOCK_X + tl.arange(0, BLOCK_X).to(
                tl.int64
            )
        else:
            offsets = block_index * BLOCK_X + tl.arange(0, BLOCK_X)
        active = offsets < n_elements
        tl.store(
            dst_ptr + offsets, tl.load(src_ptr + offsets, mask=active), mask=active
        )


def _launch_with_toolchain_retry(kernel, grid, args, launch_kwargs):
    """P02：冷编译偶发 SIGSEGV 时重试 launch；确定性失败重试耗尽后原样抛出。"""
    for attempt in range(_TOOLCHAIN_COMPILE_RETRIES):
        try:
            return kernel[grid](*args, **launch_kwargs)
        except Exception as error:
            if attempt == _TOOLCHAIN_COMPILE_RETRIES - 1:
                raise
            logger.debug(
                "_nested_view_from_jagged_copy: retrying Triton launch after "
                "toolchain failure (attempt %d): %r",
                attempt,
                error,
            )


def _launch_values_copy(src: torch.Tensor, dst: torch.Tensor) -> None:
    """平坦整块拷贝：按尺寸/字宽选宽通道或元素路径（分档见模块 docstring）。"""
    n_elements = dst.numel()
    itemsize = dst.element_size()
    total_bytes = n_elements * itemsize
    num_lanes = total_bytes // 8
    # 奇字节偏移的连续视图（如 base[1:]，is_contiguous() 为真但 data_ptr
    # 仅 2/4 字节对齐）不能安全走 int64 视图，回退元素路径保持旧版语义。
    if (
        itemsize <= 4
        and total_bytes % 8 == 0
        and total_bytes <= _I32_SAFE_BYTES
        and num_lanes >= _WIDE_LARGE_MIN_LANES
        and src.data_ptr() % 8 == 0
        and dst.data_ptr() % 8 == 0
    ):
        grid_x = min(triton.cdiv(num_lanes, _WIDE_BLOCK), _WIDE_GRID_CAP)
        chunks_per_program = triton.cdiv(num_lanes, _WIDE_BLOCK * grid_x)
        _launch_with_toolchain_retry(
            _nvj_copy_wide_kernel,
            (grid_x,),
            (
                src.view(-1).view(torch.int64),
                dst.view(-1).view(torch.int64),
                num_lanes,
                chunks_per_program,
            ),
            {
                "BLOCK_X": _WIDE_BLOCK,
                "MASKED": (num_lanes % _WIDE_BLOCK != 0) or chunks_per_program > 1,
                "num_warps": _WIDE_LARGE_WARPS,
            },
        )
        return
    if n_elements <= _FLAT_SMALL_MAX_ELEMENTS:
        _launch_with_toolchain_retry(
            _nvj_copy_flat_kernel,
            (triton.cdiv(n_elements, _FLAT_SMALL_BLOCK),),
            (src, dst, n_elements, 1),
            {
                "BLOCK_X": _FLAT_SMALL_BLOCK,
                "IDX64": False,
                "num_warps": _FLAT_SMALL_WARPS,
            },
        )
        return
    grid_x = min(triton.cdiv(n_elements, _FLAT_BLOCK), _FLAT_GRID_CAP)
    chunks_per_program = triton.cdiv(n_elements, _FLAT_BLOCK * grid_x)
    _launch_with_toolchain_retry(
        _nvj_copy_flat_kernel,
        (grid_x,),
        (src, dst, n_elements, chunks_per_program),
        {
            "BLOCK_X": _FLAT_BLOCK,
            "IDX64": n_elements > _FLAT_I32_MAX_ELEMENTS,
            "num_warps": _FLAT_WARPS,
        },
    )


def _nested_view_from_jagged_copy(
    self: torch.Tensor,
    offsets: torch.Tensor,
    dummy: torch.Tensor,
    lengths=None,
    ragged_idx=1,
    min_seqlen=None,
    max_seqlen=None,
):
    """Constructs a jagged-layout nested tensor from a flat buffer `self`,
    splitting the packed jagged dimension into batch elements according to
    `offsets` / `lengths`. The `_copy` variant owns a fresh copy of the buffer,
    which is produced here by a Triton kernel before building the nested view."""
    logger.debug("GEMS _NESTED_VIEW_FROM_JAGGED_COPY")

    src = self.contiguous() if not self.is_contiguous() else self
    values_copy = torch.empty_like(src)
    n_elements = values_copy.numel()

    if n_elements > 0:
        _launch_values_copy(src, values_copy)

    return _nested_view_from_jagged(
        values_copy,
        offsets,
        dummy,
        lengths,
        ragged_idx,
        min_seqlen,
        max_seqlen,
    )
